<?php
declare(strict_types=1);

require_once __DIR__ . '/invoices.php';

const TUMAN_BATCH_BILLING_MODES = ['FIXED_MONTHLY', 'INSTALLMENTS', 'ONETIME'];

/** @return list<array<string,mixed>> */
function tuman_batch_billing_rules(PDO $db, int $teacherId, int $batchId): array
{
    $statement=$db->prepare("SELECT r.* FROM tmn_batch_billing_rules r INNER JOIN tmn_batches b ON b.id=r.batch_id WHERE r.batch_id=:batch_id AND b.teacher_user_id=:teacher_id ORDER BY FIELD(r.billing_mode,'FIXED_MONTHLY','INSTALLMENTS','ONETIME')");
    $statement->execute(['batch_id'=>$batchId,'teacher_id'=>$teacherId]); return $statement->fetchAll();
}
/** @return array<string,mixed>|null */
function tuman_batch_billing_rule(PDO $db,int $teacherId,int $batchId,mixed $ruleId): ?array
{
    $id=filter_var($ruleId,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]); if(!$id)return null;
    $statement=$db->prepare("SELECT r.* FROM tmn_batch_billing_rules r INNER JOIN tmn_batches b ON b.id=r.batch_id WHERE r.id=:id AND r.batch_id=:batch_id AND b.teacher_user_id=:teacher_id AND r.status='ACTIVE'");
    $statement->execute(['id'=>$id,'batch_id'=>$batchId,'teacher_id'=>$teacherId]);$row=$statement->fetch();return is_array($row)?$row:null;
}
function tuman_batch_attendance_rule_id(PDO $db,int $teacherId,int $assignmentId,array $values,array $input): ?int
{
    if(($input['batch_id']??'')==='') return null;
    $batchId=filter_var($input['batch_id'],FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);
    if(!$batchId||tuman_batch_member_for_attendance($db,$teacherId,(int)$batchId,$assignmentId,$values['session_date'])===null)throw new InvalidArgumentException('The selected batch is not active for this student and date.');
    $rule=tuman_batch_billing_rule($db,$teacherId,(int)$batchId,$input['batch_billing_rule_id']??null);
    if($rule===null)throw new InvalidArgumentException('Choose an active billing rule for this batch class.');
    return (int)$rule['id'];
}
function tuman_add_batch_billing_rule(PDO $db,int $teacherId,int $batchId,array $input): void
{
    if(tuman_teacher_batch($db,$teacherId,$batchId)===null)throw new InvalidArgumentException('Batch not found.');
    $mode=$input['billing_mode']??'';$code=strtoupper(trim((string)($input['rule_code']??'')));$name=trim((string)($input['rule_name']??''));if($code==='')$code='INITIAL-'.str_replace('_','-',$mode);if($name==='')$name=ucwords(strtolower(str_replace('_',' ',$mode))).' tuition';$charge=tuman_batch_charge((string)($input['charge']??''));$currency=tuman_currency_code((string)($input['currency_code']??''));
    if(!in_array($mode,TUMAN_BATCH_BILLING_MODES,true)||preg_match('/^[A-Z0-9_-]{1,50}$/',$code)!==1||$name===''||strlen($name)>100||$charge===null||$currency===null)throw new InvalidArgumentException('Enter a valid rule code, name, billing option, charge, and currency.');
    if($mode!=='INSTALLMENTS'){$existing=$db->prepare("SELECT id FROM tmn_batch_billing_rules WHERE batch_id=:batch_id AND billing_mode=:mode AND status='ACTIVE'");$existing->execute(['batch_id'=>$batchId,'mode'=>$mode]);if($existing->fetch()!==false)throw new InvalidArgumentException('A batch can have only one active '.strtolower(str_replace('_',' ',$mode)).' rule.');}
    try{$s=$db->prepare("INSERT INTO tmn_batch_billing_rules (batch_id,rule_code,rule_name,billing_mode,charge,currency_code,status) VALUES (:batch_id,:code,:name,:mode,:charge,:currency,'ACTIVE')");$s->execute(['batch_id'=>$batchId,'code'=>$code,'name'=>$name,'mode'=>$mode,'charge'=>$charge,'currency'=>$currency]);tuman_log_activity($db,$teacherId,'BATCH_BILLING_RULE_CREATED','BATCH',$batchId,['billing_mode'=>$mode,'rule_code'=>$code]);}catch(PDOException $e){if($e->getCode()==='23000')throw new InvalidArgumentException('This batch already has that rule code.');throw $e;}
}
function tuman_generate_batch_invoices_for_rule(PDO $db,int $teacherId,int $batchId,array $input): int
{
    $rule=tuman_batch_billing_rule($db,$teacherId,$batchId,$input['batch_billing_rule_id']??null);$month=(string)($input['billing_month']??'');$dates=tuman_invoice_month_dates($month);$invoiceDate=(string)($input['invoice_date']??'');$dueDate=(string)($input['due_date']??'');
    if($rule===null)throw new InvalidArgumentException('Choose an active batch billing rule.');if($dates===null||!tuman_invoice_valid_date($invoiceDate)||($dueDate!==''&&(!tuman_invoice_valid_date($dueDate)||$dueDate<$invoiceDate)))throw new InvalidArgumentException('Enter a valid billing month, invoice date, and due date.');
    $members=array_filter(tuman_batch_members($db,$teacherId,$batchId),fn($m)=>$m['status']==='ACTIVE'&&$m['assignment_status']==='ACTIVE'&&$m['enrolled_on']<=$dates['to']);if($members===[])throw new InvalidArgumentException('This batch has no active members for that month.');
    $db->beginTransaction();try{$created=0;$amount=tuman_invoice_decimal_from_minor(tuman_invoice_minor_from_decimal((string)$rule['charge'])??0);foreach($members as $member){$duplicate=$db->prepare("SELECT id FROM tmn_invoices WHERE teacher_student_id=:assignment_id AND batch_billing_rule_id=:rule_id AND billing_period_from=:from_date AND billing_period_to=:to_date AND status<>'CANCELLED' FOR UPDATE");$duplicate->execute(['assignment_id'=>$member['teacher_student_id'],'rule_id'=>$rule['id'],'from_date'=>$dates['from'],'to_date'=>$dates['to']]);if($duplicate->fetch()!==false)continue;$number=tuman_invoice_reserve_number($db,$invoiceDate);$header=$db->prepare("INSERT INTO tmn_invoices (invoice_number,teacher_student_id,batch_id,batch_billing_rule_id,billing_period_from,billing_period_to,invoice_date,due_date,subtotal,discount_amount,total_amount,currency_code,status) VALUES (:number,:assignment_id,:batch_id,:rule_id,:from_date,:to_date,:invoice_date,:due_date,:amount,'0.00',:amount,:currency,'DRAFT')");$header->execute(['number'=>$number,'assignment_id'=>$member['teacher_student_id'],'batch_id'=>$batchId,'rule_id'=>$rule['id'],'from_date'=>$dates['from'],'to_date'=>$dates['to'],'invoice_date'=>$invoiceDate,'due_date'=>$dueDate===''?null:$dueDate,'amount'=>$amount,'currency'=>$rule['currency_code']]);$invoiceId=(int)$db->lastInsertId();$description=$rule['rule_name'].' ('.$rule['rule_code'].') — '.$month;$db->prepare("INSERT INTO tmn_invoice_items (invoice_id,description,quantity,unit_rate,amount,sort_order) VALUES (:invoice_id,:description,'1.00',:amount,:amount,1)")->execute(['invoice_id'=>$invoiceId,'description'=>$description,'amount'=>$amount]);tuman_log_activity($db,$teacherId,'BATCH_INVOICE_CREATED','INVOICE',$invoiceId,['batch_id'=>$batchId,'rule_code'=>$rule['rule_code']]);$created++;}$db->commit();if($created===0)throw new InvalidArgumentException('All active members already have a non-cancelled invoice for this rule and month.');return $created;}catch(Throwable $e){if($db->inTransaction())$db->rollBack();throw $e;}
}
/** @param array<string,mixed> $input */
function tuman_generate_batch_invoices_for_members(PDO $db,int $teacherId,int $batchId,array $input): int
{
    $batch=tuman_teacher_batch($db,$teacherId,$batchId);$month=(string)($input['billing_month']??'');$dates=tuman_invoice_month_dates($month);$invoiceDate=(string)($input['invoice_date']??'');$dueDate=(string)($input['due_date']??'');
    if($batch===null||$dates===null||!tuman_invoice_valid_date($invoiceDate)||($dueDate!==''&&(!tuman_invoice_valid_date($dueDate)||$dueDate<$invoiceDate)))throw new InvalidArgumentException('Enter a valid billing month, invoice date, and due date.');
    $members=[];foreach(tuman_batch_members($db,$teacherId,$batchId) as $member){if($member['status']==='ACTIVE'&&$member['assignment_status']==='ACTIVE'&&$member['enrolled_on']<=$dates['to'])$members[(string)$member['teacher_student_id']]=$member;}
    $choices=is_array($input['member_rule']??null)?$input['member_rule']:[];$selected=[];foreach($choices as $assignmentId=>$ruleId){$assignment=filter_var($assignmentId,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);if(!$assignment||!isset($members[(string)$assignment])||$ruleId==='')continue;$rule=tuman_batch_billing_rule($db,$teacherId,$batchId,$ruleId);if($rule===null)throw new InvalidArgumentException('Choose a valid active rule for each selected student.');$selected[(int)$assignment]=$rule;}
    if($selected===[])throw new InvalidArgumentException('Choose a billing rule for at least one batch student.');
    $db->beginTransaction();try{$created=0;foreach($selected as $assignmentId=>$rule){$duplicate=$db->prepare("SELECT id FROM tmn_invoices WHERE teacher_student_id=:assignment_id AND batch_billing_rule_id=:rule_id AND billing_period_from=:from_date AND billing_period_to=:to_date AND status<>'CANCELLED' FOR UPDATE");$duplicate->execute(['assignment_id'=>$assignmentId,'rule_id'=>$rule['id'],'from_date'=>$dates['from'],'to_date'=>$dates['to']]);if($duplicate->fetch()!==false)continue;$amount=tuman_invoice_decimal_from_minor(tuman_invoice_minor_from_decimal((string)$rule['charge'])??0);$number=tuman_invoice_reserve_number($db,$invoiceDate);$header=$db->prepare("INSERT INTO tmn_invoices (invoice_number,teacher_student_id,batch_id,batch_billing_rule_id,billing_period_from,billing_period_to,invoice_date,due_date,subtotal,discount_amount,total_amount,currency_code,status) VALUES (:number,:assignment_id,:batch_id,:rule_id,:from_date,:to_date,:invoice_date,:due_date,:subtotal,'0.00',:total,:currency,'DRAFT')");$header->execute(['number'=>$number,'assignment_id'=>$assignmentId,'batch_id'=>$batchId,'rule_id'=>$rule['id'],'from_date'=>$dates['from'],'to_date'=>$dates['to'],'invoice_date'=>$invoiceDate,'due_date'=>$dueDate===''?null:$dueDate,'subtotal'=>$amount,'total'=>$amount,'currency'=>$rule['currency_code']]);$invoiceId=(int)$db->lastInsertId();$item=$db->prepare("INSERT INTO tmn_invoice_items (invoice_id,description,quantity,unit_rate,amount,sort_order) VALUES (:invoice_id,:description,'1.00',:unit_rate,:item_amount,1)");$item->execute(['invoice_id'=>$invoiceId,'description'=>$rule['rule_name'].' ('.$rule['rule_code'].') — '.$batch['batch_name'].' — '.$month,'unit_rate'=>$amount,'item_amount'=>$amount]);tuman_log_activity($db,$teacherId,'BATCH_INVOICE_CREATED','INVOICE',$invoiceId,['batch_id'=>$batchId,'rule_code'=>$rule['rule_code']]);$created++;}$db->commit();if($created===0)throw new InvalidArgumentException('Selected students already have non-cancelled draft or issued invoices for those rules and month.');return $created;}catch(Throwable $e){if($db->inTransaction())$db->rollBack();throw $e;}
}

function tuman_batch_date(string $date): bool { return tuman_invoice_valid_date($date); }
function tuman_batch_charge(string $value): ?string { return tuman_billing_normalize_rate(trim($value)); }
/** @return array<string,string> */
function tuman_validate_batch(array $input): array {
    $errors=[]; $name=trim((string)($input['batch_name']??''));
    if($name===''||strlen($name)>150)$errors['batch_name']='Batch name is required and must be 150 characters or fewer.';
    foreach(['objective'=>'Objective','teacher_responsibility'=>"Teacher's responsibility",'student_responsibility'=>"Student's responsibility",'batch_terms'=>'Batch terms'] as $field=>$label){if(strlen((string)($input[$field]??''))>5000)$errors[$field]=$label.' must be 5,000 characters or fewer.';}
    if(!in_array($input['billing_mode']??'',TUMAN_BATCH_BILLING_MODES,true))$errors['billing_mode']='Choose a valid batch billing rule.';
    if(tuman_batch_charge((string)($input['charge']??''))===null)$errors['charge']='Charges must be a non-negative amount with no more than two decimal places.';
    if(tuman_currency_code((string)($input['currency_code']??''))===null)$errors['currency_code']='Choose a supported currency.';
    return $errors;
}
/** @return array<string,?string> */
function tuman_batch_values(array $input): array { $errors=tuman_validate_batch($input);if($errors!==[])throw new InvalidArgumentException(reset($errors));$values=[];foreach(['batch_name','objective','teacher_responsibility','student_responsibility','batch_terms'] as $key){$value=trim((string)($input[$key]??''));$values[$key]=$value===''?null:$value;}$values['batch_name']=(string)$values['batch_name'];$values['billing_mode']=$input['billing_mode'];$values['charge']=tuman_batch_charge((string)$input['charge']);$values['currency_code']=tuman_currency_code((string)$input['currency_code']);return $values; }
/** @return list<array<string,mixed>> */
function tuman_teacher_batches(PDO $db,int $teacherId): array {$s=$db->prepare("SELECT b.*,COUNT(CASE WHEN bs.status='ACTIVE' THEN 1 END) member_count FROM tmn_batches b LEFT JOIN tmn_batch_students bs ON bs.batch_id=b.id WHERE b.teacher_user_id=:teacher_id GROUP BY b.id ORDER BY b.status='ACTIVE' DESC,b.batch_name");$s->execute(['teacher_id'=>$teacherId]);return $s->fetchAll();}
/** @return array<string,mixed>|null */
function tuman_teacher_batch(PDO $db,int $teacherId,int $batchId): ?array {$s=$db->prepare('SELECT * FROM tmn_batches WHERE id=:id AND teacher_user_id=:teacher_id');$s->execute(['id'=>$batchId,'teacher_id'=>$teacherId]);$row=$s->fetch();return is_array($row)?$row:null;}
/** @return list<array<string,mixed>> */
function tuman_batch_members(PDO $db,int $teacherId,int $batchId): array {$s=$db->prepare("SELECT bs.*,ts.student_user_id,ts.status assignment_status,sp.first_name,sp.last_name,u.email FROM tmn_batch_students bs INNER JOIN tmn_batches b ON b.id=bs.batch_id INNER JOIN tmn_teacher_students ts ON ts.id=bs.teacher_student_id INNER JOIN tmn_student_profiles sp ON sp.user_id=ts.student_user_id INNER JOIN tmn_users u ON u.id=ts.student_user_id WHERE bs.batch_id=:batch_id AND b.teacher_user_id=:teacher_id ORDER BY bs.status='ACTIVE' DESC,sp.first_name,sp.last_name");$s->execute(['batch_id'=>$batchId,'teacher_id'=>$teacherId]);return $s->fetchAll();}
function tuman_create_batch(PDO $db,int $teacherId,array $input): int {$v=tuman_batch_values($input);try{$s=$db->prepare("INSERT INTO tmn_batches (teacher_user_id,batch_name,objective,teacher_responsibility,student_responsibility,batch_terms,billing_mode,charge,currency_code) VALUES (:teacher_id,:batch_name,:objective,:teacher_responsibility,:student_responsibility,:batch_terms,:billing_mode,:charge,:currency_code)");$s->execute(['teacher_id'=>$teacherId]+$v);$id=(int)$db->lastInsertId();tuman_log_activity($db,$teacherId,'BATCH_CREATED','BATCH',$id,['billing_mode'=>$v['billing_mode'],'currency_code'=>$v['currency_code']]);return $id;}catch(PDOException $e){if($e->getCode()==='23000')throw new InvalidArgumentException('You already have a batch with that name.');throw $e;}}
function tuman_update_batch(PDO $db,int $teacherId,int $batchId,array $input):void {if(tuman_teacher_batch($db,$teacherId,$batchId)===null)throw new InvalidArgumentException('Batch not found.');$v=tuman_batch_values($input);try{$s=$db->prepare('UPDATE tmn_batches SET batch_name=:batch_name,objective=:objective,teacher_responsibility=:teacher_responsibility,student_responsibility=:student_responsibility,batch_terms=:batch_terms,billing_mode=:billing_mode,charge=:charge,currency_code=:currency_code WHERE id=:id AND teacher_user_id=:teacher_id');$s->execute($v+['id'=>$batchId,'teacher_id'=>$teacherId]);tuman_log_activity($db,$teacherId,'BATCH_UPDATED','BATCH',$batchId,['billing_mode'=>$v['billing_mode']]);}catch(PDOException $e){if($e->getCode()==='23000')throw new InvalidArgumentException('You already have a batch with that name.');throw $e;}}
function tuman_add_batch_member(PDO $db,int $teacherId,int $batchId,int $assignmentId,string $enrolledOn):void {if(!tuman_batch_date($enrolledOn))throw new InvalidArgumentException('Enter a valid enrolment date.');$batch=tuman_teacher_batch($db,$teacherId,$batchId);$student=tuman_teacher_student($db,$teacherId,$assignmentId);if($batch===null||$batch['status']!=='ACTIVE'||$student===null||$student['assignment_status']!=='ACTIVE')throw new InvalidArgumentException('Choose an active batch and one of your active students.');if($enrolledOn<$student['start_date']||($student['end_date']!==null&&$enrolledOn>$student['end_date']))throw new InvalidArgumentException('Enrolment date must fall within the student assignment dates.');$existing=$db->prepare('SELECT id,status FROM tmn_batch_students WHERE batch_id=:batch_id AND teacher_student_id=:assignment_id FOR UPDATE');$existing->execute(['batch_id'=>$batchId,'assignment_id'=>$assignmentId]);$row=$existing->fetch();if(is_array($row)){if($row['status']==='ACTIVE')throw new InvalidArgumentException('This student is already in the batch.');$db->prepare("UPDATE tmn_batch_students SET status='ACTIVE',enrolled_on=:enrolled_on WHERE id=:id")->execute(['enrolled_on'=>$enrolledOn,'id'=>$row['id']]);}else{$db->prepare("INSERT INTO tmn_batch_students (batch_id,teacher_student_id,enrolled_on,status) VALUES (:batch_id,:assignment_id,:enrolled_on,'ACTIVE')")->execute(['batch_id'=>$batchId,'assignment_id'=>$assignmentId,'enrolled_on'=>$enrolledOn]);}tuman_log_activity($db,$teacherId,'BATCH_MEMBER_ADDED','BATCH',$batchId,['assignment_id'=>$assignmentId]);}
function tuman_remove_batch_member(PDO $db,int $teacherId,int $batchId,int $memberId):void {$s=$db->prepare("UPDATE tmn_batch_students bs INNER JOIN tmn_batches b ON b.id=bs.batch_id SET bs.status='INACTIVE' WHERE bs.id=:id AND bs.batch_id=:batch_id AND b.teacher_user_id=:teacher_id AND bs.status='ACTIVE'");$s->execute(['id'=>$memberId,'batch_id'=>$batchId,'teacher_id'=>$teacherId]);if($s->rowCount()!==1)throw new InvalidArgumentException('Batch member not found.');tuman_log_activity($db,$teacherId,'BATCH_MEMBER_REMOVED','BATCH',$batchId,['member_id'=>$memberId]);}
/** @return array<string,mixed>|null */
function tuman_batch_member_for_attendance(PDO $db,int $teacherId,int $batchId,int $assignmentId,string $date):?array {$s=$db->prepare("SELECT bs.* FROM tmn_batch_students bs INNER JOIN tmn_batches b ON b.id=bs.batch_id WHERE bs.batch_id=:batch_id AND bs.teacher_student_id=:assignment_id AND bs.status='ACTIVE' AND b.teacher_user_id=:teacher_id AND b.status='ACTIVE' AND bs.enrolled_on<=:session_date");$s->execute(['batch_id'=>$batchId,'assignment_id'=>$assignmentId,'teacher_id'=>$teacherId,'session_date'=>$date]);$row=$s->fetch();return is_array($row)?$row:null;}
function tuman_batch_attendance_id(PDO $db,int $teacherId,int $assignmentId,array $values,array $input):?int {if(($input['batch_id']??'')==='')return null;$id=filter_var($input['batch_id'],FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);if(!$id||tuman_batch_member_for_attendance($db,$teacherId,(int)$id,$assignmentId,$values['session_date'])===null)throw new InvalidArgumentException('The selected batch is not active for this student and date.');return (int)$id;}
function tuman_generate_batch_invoices(PDO $db,int $teacherId,int $batchId,array $input):int {$batch=tuman_teacher_batch($db,$teacherId,$batchId);$month=(string)($input['billing_month']??'');$dates=tuman_invoice_month_dates($month);$invoiceDate=(string)($input['invoice_date']??'');$dueDate=(string)($input['due_date']??'');if($batch===null||$batch['status']!=='ACTIVE')throw new InvalidArgumentException('Batch not found.');if($dates===null||!tuman_invoice_valid_date($invoiceDate)||($dueDate!==''&&(!tuman_invoice_valid_date($dueDate)||$dueDate<$invoiceDate)))throw new InvalidArgumentException('Enter a valid billing month, invoice date, and due date.');$members=tuman_batch_members($db,$teacherId,$batchId);$members=array_filter($members,fn($m)=>$m['status']==='ACTIVE'&&$m['assignment_status']==='ACTIVE'&&$m['enrolled_on']<=$dates['to']);if($members===[])throw new InvalidArgumentException('This batch has no active members for that month.');$db->beginTransaction();try{$created=0;foreach($members as $member){$dup=$db->prepare("SELECT id FROM tmn_invoices WHERE teacher_student_id=:assignment_id AND batch_id=:batch_id AND billing_period_from=:from_date AND billing_period_to=:to_date AND status<>'CANCELLED' FOR UPDATE");$dup->execute(['assignment_id'=>$member['teacher_student_id'],'batch_id'=>$batchId,'from_date'=>$dates['from'],'to_date'=>$dates['to']]);if($dup->fetch()!==false)continue;$number=tuman_invoice_reserve_number($db,$invoiceDate);$amount=tuman_invoice_decimal_from_minor(tuman_invoice_minor_from_decimal((string)$batch['charge'])??0);$header=$db->prepare("INSERT INTO tmn_invoices (invoice_number,teacher_student_id,batch_id,billing_period_from,billing_period_to,invoice_date,due_date,subtotal,discount_amount,total_amount,currency_code,status) VALUES (:number,:assignment_id,:batch_id,:from_date,:to_date,:invoice_date,:due_date,:amount,'0.00',:amount,:currency,'DRAFT')");$header->execute(['number'=>$number,'assignment_id'=>$member['teacher_student_id'],'batch_id'=>$batchId,'from_date'=>$dates['from'],'to_date'=>$dates['to'],'invoice_date'=>$invoiceDate,'due_date'=>$dueDate===''?null:$dueDate,'amount'=>$amount,'currency'=>$batch['currency_code']]);$invoiceId=(int)$db->lastInsertId();$label=match($batch['billing_mode']){'FIXED_MONTHLY'=>'Monthly batch tuition','INSTALLMENTS'=>'Batch tuition instalment','ONETIME'=>'One-time batch tuition'};$db->prepare('INSERT INTO tmn_invoice_items (invoice_id,description,quantity,unit_rate,amount,sort_order) VALUES (:invoice_id,:description,\'1.00\',:amount,:amount,1)')->execute(['invoice_id'=>$invoiceId,'description'=>$label.' — '.$batch['batch_name'].' — '.$month,'amount'=>$amount]);tuman_log_activity($db,$teacherId,'BATCH_INVOICE_CREATED','INVOICE',$invoiceId,['batch_id'=>$batchId,'billing_mode'=>$batch['billing_mode']]);$created++;}$db->commit();if($created===0)throw new InvalidArgumentException('All active members already have a non-cancelled batch invoice for that month.');return $created;}catch(Throwable $e){if($db->inTransaction())$db->rollBack();throw $e;}}
